    lander = sandbox.get_lander_body()
    return lander

def agent_action(sandbox, agent_body, step_count):
    # Get current position
    pos = sandbox.get_lander_position()
    x, y = pos

    # Get current angle
    angle = sandbox.get_lander_angle()

    # Get half_width and half_height
    half_width, half_height = sandbox.get_lander_size()

    # Check if in no-fly zone
    in_no_fly = False
    for dx in [-half_width, half_width]:
        for dy in [-half_height, half_height]:
            corner_x = x + dx
            corner_y = y + dy
            if 10.5 <= corner_x <= 13.5:
                if corner_y < 6.0 or corner_y > 20.0:
                    in_no_fly = True
                    break
        if in_no_fly:
            break

    # Check if near ground
    ground_y = sandbox.get_ground_y_top()
    near_ground = (y - ground_y) < 0.02

    # Calculate platform position
    time = step_count / 60.0
    platform_x = 17.0 + 1.8 * math.sin((math.pi / 3) * time)
    platform_valid_start = platform_x - 2.0
    platform_valid_end = platform_x + 2.0

    # Get remaining fuel
    fuel = sandbox.get_remaining_fuel()

    # Determine thrust and torque
    thrust = 0
    torque = 0

    if in_no_fly:
        # Adjust vertical thrust to keep y within bounds
        if y < 6.0:
            thrust = 500  # upward thrust
        elif y > 20.0:
            thrust = -500  # downward thrust
        else:
            thrust = 0
    else:
        # Not in no-fly zone, track platform
        if near_ground:
            # Check if within platform's valid area
            if platform_valid_start <= x <= platform_valid_end:
                # Apply upward thrust to slow down
                thrust = 500
            else:
                # Move towards platform
                if x < platform_valid_start:
                    thrust = 500
                else:
                    thrust = -500
        else:
            # Calculate distance to platform
            error_x = platform_x - x
            if error_x > 0:
                # Platform is ahead, slow down
                thrust = -500
            else:
                # Platform is behind, speed up
                thrust = 500

        # Check angle and apply torque
        if abs(angle) > math.radians(10):
            if angle > 0:
                torque = 120  # clockwise
            else:
                torque = -120  # counter-clockwise
        else:
            torque = 0

    # Check fuel
    if fuel < 450:
        thrust = 0

    # Apply thrust and torque
    sandbox.apply_thrust(thrust, torque)
